async function buatToken(payload) {
  const kepala = teksKeB64(JSON.stringify({ alg: "HS256", typ: "JWT" }));
  const isi = teksKeB64(JSON.stringify(payload));
  return `${kepala}.${isi}.${await tanda(`${kepala}.${isi}`)}`;
