  if ((await tanda(`${k}.${i}`)) !== s) return "tanda tangan tidak valid";
  const p = JSON.parse(b64KeTeks(i));
  return sekarang > p.exp ? "kedaluwarsa" : `valid: user ${p.sub}, peran ${p.peran}`;
