const potongan = ["Kopi ", "Gayo ", "berasal ", "dari ", "Aceh."];
const res = new Response(new ReadableStream({
  start(c) { for (const p of potongan) c.enqueue(new TextEncoder().encode(p)); c.close(); },
}));

const reader = res.body.getReader();
const dec = new TextDecoder();
let layar = "";
while (true) {
  const { value, done } = await reader.read();
  if (done) break;
  layar += dec.decode(value, { stream: true });
  console.log("tampil:", layar);
}

